cmsis-pack-trace-snippet.debugvars:
// TPIU
__var TPIU___INSTANCE_INDEX___ADDRESS     = 0xE0040000;  // Default TPIU Location for single-core systems
__var TPIU___INSTANCE_INDEX___AP          = 0x00000000;
__var TPIU___INSTANCE_INDEX___PRESCALER   = 0x00000000;  // Clock divider (ACPR + 1); zero derives it from the trace clocks

sequence.block:
__var swoTrace    = __traceout & 0x1;
__var syncTrace   = __traceout & 0x2;
__var tracePortWidth = (__traceout >> 16) & 0x3F;       // Parallel trace port size
__var prescaler   = TPIU___INSTANCE_INDEX___PRESCALER;

// Helper variables
__var ffcrValue = 0x00000000;
__var LAR_KEY   = 0xC5ACCE55;
__var savedAP = __ap;

Message(0, "Begin CS_TPIU___INSTANCE_INDEX___Configure @0x%08X, AP 0x%08X", TPIU___INSTANCE_INDEX___ADDRESS, TPIU___INSTANCE_INDEX___AP);

// Helper variables
__var savedAP = __ap;
__var ffcrValue = 0x00000000;

Message(0, "Begin CS_TPIU___INSTANCE_INDEX___Capture @0x%08X, AP 0x%08X", TPIU___INSTANCE_INDEX___ADDRESS, TPIU___INSTANCE_INDEX___AP);

// Configure TPIU if needed and enable formatter
__ap = TPIU___INSTANCE_INDEX___AP;                            // Set AP
ffcrValue  = Read32(TPIU___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue |= 0x00000002;                                      // Enable continuous formatting
Write32(TPIU___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);  // TPIU FFCR
__ap = savedAP;
Message(0, "End CS_TPIU___INSTANCE_INDEX___Capture @0x%08X, AP 0x%08X", TPIU___INSTANCE_INDEX___ADDRESS, TPIU___INSTANCE_INDEX___AP);

// Helper variables
__var savedAP     = __ap;
__var ffcrValue   = 0x00000000;
__var ffsrValue   = 0x00000000;

Message(0, "Begin CS_TPIU___INSTANCE_INDEX___Flush @0x%08X, AP 0x%08X", TPIU___INSTANCE_INDEX___ADDRESS, TPIU___INSTANCE_INDEX___AP);

__ap = TPIU___INSTANCE_INDEX___AP;  // Set AP

control.block:
// Flush the TPIU formatter so pending packets leave the trace port.
ffcrValue = Read32(TPIU___INSTANCE_INDEX___ADDRESS + 0x304);
ffcrValue &= ~(0x00001040);   // Clear StopOnFlush and FlushOnManual
ffcrValue |= 0x00001000;          // Stop after the manual flush completes
Write32(TPIU___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
ffcrValue |= 0x00000040;          // Trigger manual flush
Write32(TPIU___INSTANCE_INDEX___ADDRESS + 0x304, ffcrValue);
